    body {
      margin: 0;
      padding: 0;
      background-color: #e5ddd5;
      color: #000000;
    }
    table, td, tr { border-collapse: collapse; vertical-align: top; }
    .ie-container table, .mso-container table { table-layout: fixed; }
    * {
      line-height: inherit;
      margin: 0;
      padding: 0;
      font-family: 'Segoe UI', Helvetica, Arial, sans-serif;
    }
    a[x-apple-data-detectors=true] {
      color: inherit !important;
      text-decoration: none !important;
    }
    #u_body a {
      color: #0000ee;
      text-decoration: underline;
    }

    /* ===== CALENDAR & INTERVIEW SECTION ===== */
    .calendar-container {
      width: 100%;
      border: 1px solid #dadce0;
      border-radius: 8px;
      max-width: 700px;
      margin: 0 auto;
    }

    /* Time Slots - Desktop */
    .time-slot {
      text-decoration: none;
      background-color: #f1f3f4;
      color: #202124;
      font-size: 12px;
      padding: 6px 4px;
      border-radius: 6px;
      border: 1px solid #dadce0;
      display: inline-block;
      transition: all 0.2s ease;
      width: 20%;
      min-width: 100px;
      box-sizing: border-box;
      text-align: center;
      margin-right: 1%;
    }

    .time-slot:last-child {
      margin-right: 0;
    }

    .time-slot:hover {
      background-color: #e0e0e0;
      cursor: pointer;
    }

    /* ===== WHATSAPP CHAT STYLES ===== */
    .chat-container-table {
      width: 100%;
      max-width: 500px;
      background-color: #fff;
      border-radius: 10px;
      overflow: hidden;
      box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
      margin: 10px auto;
    }
    
    .chat-header-cell {
      background-color: #075e54;
      color: white;
      padding: 10px;
    }
    
    .profile-pic-table {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background-color: #25d366;
      text-align: center;
      line-height: 40px;
      color: white;
      font-weight: bold;
      font-size: 18px;
    }
    
    .contact-name {
      font-weight: 500;
      font-size: 16px;
      color: white;
      margin-bottom: -10px;
    }
    
    .contact-status {
      font-size: 13px;
      opacity: 0.8;
      color: white;
      padding-top: 5px;
    }
    
    .header-icons-table {
      text-align: right;
      color: white;
      font-size: 18px;
      padding-right: 20px;
    }
    
    .header-icons-table i {
      margin-left: 15px;
    }
    
    .chat-body-cell {
      background-color: #e5ddd5;
      background-image: url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0MCIgaGVpZ2h0PSI0MCIgdmlld0JveD0iMCAwIDQwIDQwIj48cGF0aCBmaWxsPSIjZWRmNWYxIiBkPSJNMCAwaDQwdjQwSDB6Ii8+PHBhdGggZmlsbD0iI2RkZTRlOCIgZD0iTTAgMGgyMHY0MEgweiIvPjwvc3ZnPg==');
      background-size: 40px 40px;
      padding: 15px;
    }
    
    .message-table {
      max-width: 75%;
      padding: 8px 12px;
      margin-bottom: 10px;
      border-radius: 8px;
      word-wrap: break-word;
      box-shadow: 0 1px 0.5px rgba(0, 0, 0, 0.13);
      font-size: 13px !important;
    }
    
    .received-table {
      background-color: white;
      border-top-left-radius: 0;
    }
    
    .message-time {
      font-size: 11px;
      color: rgba(0, 0, 0, 0.45);
      text-align: right;
      margin-top: 2px;
    }
    
    .attachment-table {
      background-color: white;
      border-radius: 5px;
      padding: 10px;
      margin-top: 8px;
      border: 1px solid #e0e0e0;
    }
    
    .attachment-icon-table {
      width: 40px;
      height: 40px;
      background-color: #e74c3c;
      border-radius: 5px;
      text-align: center;
      line-height: 40px;
      color: white;
      font-size: 18px;
    }
    
    .attachment-name {
      font-weight: 500;
      font-size: 14px;
      margin-bottom: 3px;
    }
    
    .attachment-info {
      font-size: 12px;
      color: rgba(0, 0, 0, 0.6);
    }
    
    .attachment-size {
      font-weight: 500;
    }
    
    .download-btn-table {
      background-color: #075e54;
      color: white;
      border: none;
      padding: 5px 10px;
      border-radius: 3px;
      font-size: 12px;
      cursor: pointer;
      margin-right: 10px;
    }
    
    .chat-footer-cell {
      padding: 10px 15px;
      background-color: #f0f0f0;
    }
    
    .footer-icons-table {
      color: #54656f;
      font-size: 20px;
    }
    
    .footer-icons-table i {
      margin-right: 15px;
    }
    
    .message-input-container-table {
      background-color: white;
      border-radius: 20px;
      padding: 5px 15px;
    }
    
    .message-input-table {
      border: none;
      outline: none;
      font-size: 15px;
      background: transparent;
      width: 100%;
      padding: 9px 5px;
    }
    
    .send-button-table {
      background-color: #075e54;
      color: white;
      border: none;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      text-align: center;
      line-height: 40px;
    }
    
    .typing-indicator-table {
      background-color: white;
      color: #969696;
      border-radius: 8px;
      border-top-left-radius: 0;
      padding: 8px 12px;
      max-width: 75%;
      margin-bottom: 10px;
      font-size: 12px;
    }
    
    .date-divider {
      text-align: center;
      margin: 10px 0;
      font-size: 12px;
      color: rgba(0, 0, 0, 0.45);
    }

    /* ===== MOBILE STYLES (480px and below) ===== */
    @media (max-width: 480px) {
      body { padding: 0; }
      
      /* Logo spacing */
      #u_content_image_14 .v-container-padding-padding {
        padding: 5px 0px 0px !important;
      }
      
      /* Time Slots Mobile Optimization - ALL 3 SLOTS SIDE BY SIDE */
            /* Time Slots Mobile Optimization - FORCE ALL 3 SLOTS SIDE BY SIDE */
      .time-slot {
        width: 24% !important;
        margin-right: 0.5% !important;
        padding: 1px 0px !important;
        font-size: 5px !important;
        min-width: 0 !important;
        display: inline-block !important;
        line-height: 1 !important;
        letter-spacing: -0.2px !important;
      }

      .time-slot:nth-child(3) {
        margin-right: 0 !important;
      }
      
      td[style*="padding-top:8px"] {
        text-align: center !important;
        font-size: 0 !important;
        white-space: nowrap !important;
        padding: 2px 0px 1px 0px !important;
        line-height: 0 !important;
      }
      
      td[style*="padding-top:8px"] > .time-slot {
        font-size: 5px !important;
      }

      /* Layout adjustments */
      .mobile-stack { display: block !important; width: 100% !important; }
      .mobile-hide { display: none !important; }
      .mobile-full-width { width: 100% !important; }
      
      /* Button adjustments */
      .mobile-btn {
        width: 100% !important;
        max-width: 200px !important;
        margin: 4px auto !important;
        display: block !important;
      }
      
      /* Chat adjustments for mobile */
      .chat-container-table {
        border-radius: 0;
        width: 100% !important;
        max-width: 100% !important;
      }
      .message-table { max-width: 85% !important; }
      .header-icons-table { padding-right: 10px !important; }
      .header-icons-table i { margin-left: 10px !important; }
      .chat-body-cell { padding: 10px !important; }
      .footer-icons-table i { margin-right: 10px !important; }
      
      /* Scroll message positioning */
      td[style*="border-left:1px solid #dadce0; padding-left:20px;"] {
        border-left: none !important;
        padding-left: 0 !important;
        border-top: 1px solid #dadce0 !important;
        padding-top: 20px !important;
        margin-top: 20px !important;
      }
    }

    /* ===== DESKTOP STYLES (481px and above) ===== */
    @media (min-width: 481px) {
      .time-slot {
        width: 32% !important;
        margin-right: 1% !important;
      }
      
      .time-slot:last-child {
        margin-right: 0 !important;
      }
    }
  

  
  



  
  
  
    
      
        
          

          
          
            
              
                
                
                  
                    

                      
  
    
      
        
          
            
              
              
            
          
        
      
    
  



  
    
      
        
        
      
    
  


                    
                  
                
                
                
              
            
          

          
          
            
              
                
                  
                  
                  
                    
                      
                        
